challenge.starter:
const scans = [3, 7, -1, 12, 0, 5, 99, 4];
let total = 0;
let valid = 0;

// Döngüyle topla (continue ve break kullan)

console.log("Geçerli ölçüm:", valid, "| Toplam:", total);

challenge.solution:
const scans = [3, 7, -1, 12, 0, 5, 99, 4];
let total = 0;
let valid = 0;

// Döngüyle topla (continue ve break kullan)
for (const value of scans) {
  if (value === 99) {
    break;
  }
  if (value < 0) {
    continue;
  }
  total += value;
  valid++;
}

console.log("Geçerli ölçüm:", valid, "| Toplam:", total);

check.js:
assert(total === 27, "total 27 olmalı (3 + 7 + 12 + 0 + 5).");
assert(valid === 5, "valid 5 olmalı.");
assert(!/27/.test(_code), "Sonucu elle yazma; döngü hesaplasın.");

