project_task.solution:
const tasks = ["Matematik ödevi", "Kitap okuma", "İngilizce kelime", "Oda toplama"];
const done = [true, false, false, true];
let doneCount = 0;

// Döngüyle listeyi yazdır ve biten görevleri say
for (let i = 0; i < tasks.length; i++) {
  const box = done[i] ? "[x]" : "[ ]";
  console.log(`${i + 1}. ${box} ${tasks[i]}`);
  if (done[i]) {
    doneCount++;
  }
}

// Tamamlanan satırını yazdır
console.log(`Tamamlanan: ${doneCount}/${tasks.length}`);

check.js:
assert(doneCount === 2, "doneCount 2 olmalı.");
assert(_lines.join("|") === "1. [x] Matematik ödevi|2. [ ] Kitap okuma|3. [ ] İngilizce kelime|4. [x] Oda toplama|Tamamlanan: 2/4", "Çıktı numaralı 4 görev satırı ve 'Tamamlanan: 2/4' olmalı.");
assert((_code.match(/console\.log/g) || []).length <= 3, "Her görev için ayrı console.log yazma; döngü kullan.");
assert(!/2\/4/.test(_code), "Sayıları elle yazma; doneCount ve tasks.length kullan.");

