project_task.solution:
const questions = ["Ay, hangi gezegenin uydusudur?", "Güneş sistemindeki en büyük gezegen hangisidir?", "Kızıl gezegen olarak bilinen gezegen hangisidir?"];
const answers = ["Dünya", "Jüpiter", "Mars"];
const userAnswers = ["Dünya", "Satürn", "Mars"];
let correctCount = 0;

// Soruları yazdır ve doğruları say
for (let i = 0; i < questions.length; i++) {
  console.log(`Soru ${i + 1}: ${questions[i]}`);
  if (userAnswers[i] === answers[i]) {
    correctCount++;
  }
}

// Sonucu yazdır
console.log(`Doğru sayısı: ${correctCount}/${questions.length}`);

check.js:
assert(correctCount === 2, "correctCount 2 olmalı.");
assert(_lines[0] === "Soru 1: Ay, hangi gezegenin uydusudur?" && _lines[1] === "Soru 2: Güneş sistemindeki en büyük gezegen hangisidir?" && _lines[2] === "Soru 3: Kızıl gezegen olarak bilinen gezegen hangisidir?", "İlk üç satır 'Soru 1: ...', 'Soru 2: ...', 'Soru 3: ...' olmalı.");
assert(_lines.includes("Doğru sayısı: 2/3"), "Çıktıda 'Doğru sayısı: 2/3' görünmeli.");
assert((_code.match(/console\.log/g) || []).length <= 2, "Her soru için ayrı console.log yazma; döngü kullan.");
assert(!/2\/3/.test(_code) && !/Soru 2/.test(_code), "Sayıları elle yazma; döngü ve sayaç kullan.");
